// Original compositions. All tones and percussion are synthesized at runtime.
export class ArcadeAudio {
 constructor(){this.enabled=false;this.stage=0;this.step=0;this.next=0;this.ctx=null;this.master=null;this.timer=null;this.music=true;}
 async start(){if(!this.ctx){const AC=globalThis.AudioContext||globalThis.webkitAudioContext;if(!AC)return false;this.ctx=new AC();this.master=this.ctx.createGain();this.master.gain.value=.22;this.master.connect(this.ctx.destination);const buffer=this.ctx.createBuffer(1,this.ctx.sampleRate*.25,this.ctx.sampleRate);const data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;this.noiseBuffer=buffer;this.timer=setInterval(()=>this.schedule(),45);}await this.ctx.resume();this.enabled=true;this.master.gain.setTargetAtTime(.22,this.ctx.currentTime,.03);this.next=this.ctx.currentTime+.05;return true;}
 mute(){this.enabled=false;if(this.master)this.master.gain.setTargetAtTime(0,this.ctx.currentTime,.025);}
 setStage(stage){this.stage=stage;this.step=0;if(this.ctx)this.next=this.ctx.currentTime+.05;}
 tone(note,time,duration=.12,type='square',volume=.13,slide=0){if(!this.ctx||!this.enabled)return;const osc=this.ctx.createOscillator(),g=this.ctx.createGain();osc.type=type;const f=440*2**((note-69)/12);osc.frequency.setValueAtTime(f,time);if(slide)osc.frequency.exponentialRampToValueAtTime(Math.max(25,f*slide),time+duration);g.gain.setValueAtTime(.001,time);g.gain.linearRampToValueAtTime(volume,time+.006);g.gain.exponentialRampToValueAtTime(.001,time+duration);osc.connect(g);g.connect(this.master);osc.start(time);osc.stop(time+duration+.01);}
 noise(time,duration,volume,cutoff){const source=this.ctx.createBufferSource(),filter=this.ctx.createBiquadFilter(),g=this.ctx.createGain();source.buffer=this.noiseBuffer;filter.type='highpass';filter.frequency.value=cutoff;g.gain.setValueAtTime(volume,time);g.gain.exponentialRampToValueAtTime(.001,time+duration);source.connect(filter);filter.connect(g);g.connect(this.master);source.start(time);source.stop(time+duration);}
 schedule(){if(!this.enabled||!this.music||!this.ctx)return;const now=this.ctx.currentTime;if(this.next<now-.2)this.next=now+.02;while(this.next<now+.15){this.tick(this.step++,this.next);this.next+=60/[104,118,96][this.stage]/4;}}
 tick(step,t){const s=step%64,beat=s%16,bar=Math.floor(s/16);const roots=[[40,40,45,47],[38,41,43,45],[45,41,43,40]][this.stage];const root=roots[bar];const bass=[[0,0,7,10,12,10,7,3],[0,12,0,7,10,7,3,7],[0,7,12,7,3,7,10,7]][this.stage];if(s%2===0)this.tone(root+bass[(s/2)%8],t,.19,'triangle',.38);if(s%8===0)this.tone(35,t,.16,'sine',.65,.17);if(s%8===4)this.noise(t,.12,.3,900);if(s%2===0)this.noise(t,.028,s%4===0?.08:.045,7000);if([2,7,10,14].includes(beat)){this.tone(root+24,t,.08,'square',.055);this.tone(root+27,t,.085,'square',.035);this.tone(root+31,t,.09,'triangle',.09);}const melody=[[12,null,15,19,null,17,15,10,12,19,null,22,19,17,null,15],[19,22,null,19,15,12,10,null,12,15,17,null,19,17,15,10],[12,null,19,15,14,null,10,7,12,15,null,19,17,15,14,null]][this.stage];if(s%4===0&&melody[s/4]!==null)this.tone(root+12+melody[s/4],t,.25,this.stage===2?'triangle':'sawtooth',.045);}
 effect(type){if(!this.enabled||!this.ctx)return;const t=this.ctx.currentTime;if(type==='hit'){this.tone(36,t,.1,'square',.45,.35);this.noise(t,.055,.3,600);}else if(type==='hurt'){this.tone(43,t,.16,'sawtooth',.35,.4);}else if(type==='special'){[64,67,71,76].forEach((n,i)=>this.tone(n,t+i*.045,.12,'square',.16));}else if(type==='pickup'){this.tone(76,t,.1,'square',.2);this.tone(83,t+.09,.17,'square',.2);}else if(type==='ko'){this.tone(40,t,.22,'triangle',.5,.15);}else if(type==='block'){this.noise(t,.07,.24,3000);}else if(type==='jump'){this.tone(45,t,.12,'triangle',.17,2.5);}else if(type==='swing'){this.noise(t,.035,.06,2000);}else if(type==='select'){this.tone(76,t,.06,'square',.14);}}
}
